'use client';

import { ContextMenu as ContextMenuPrimitive } from 'radix-ui';

import {
  createCheckboxItem,
  createContent,
  createItem,
  createItemIndicator,
  createOpenRoot,
  createPortal,
  createRadioGroup,
  createRadioItem,
  type IndicatorAnimationProps,
  type PresenceAnimationProps,
} from './context-menu-animated-menu';

type ContextMenuProps = ContextMenuPrimitive.ContextMenuProps;
type ContextMenuTriggerProps = ContextMenuPrimitive.ContextMenuTriggerProps;
type ContextMenuPortalProps = ContextMenuPrimitive.ContextMenuPortalProps;
type ContextMenuContentProps = ContextMenuPrimitive.ContextMenuContentProps &
  PresenceAnimationProps;
type ContextMenuGroupProps = ContextMenuPrimitive.ContextMenuGroupProps;
type ContextMenuLabelProps = ContextMenuPrimitive.ContextMenuLabelProps;
type ContextMenuItemProps = ContextMenuPrimitive.ContextMenuItemProps;
type ContextMenuCheckboxItemProps =
  ContextMenuPrimitive.ContextMenuCheckboxItemProps;
type ContextMenuRadioGroupProps =
  ContextMenuPrimitive.ContextMenuRadioGroupProps;
type ContextMenuRadioItemProps = ContextMenuPrimitive.ContextMenuRadioItemProps;
type ContextMenuItemIndicatorProps =
  ContextMenuPrimitive.ContextMenuItemIndicatorProps & IndicatorAnimationProps;
type ContextMenuSeparatorProps = ContextMenuPrimitive.ContextMenuSeparatorProps;
type ContextMenuArrowProps = ContextMenuPrimitive.ContextMenuArrowProps;
type ContextMenuSubProps = ContextMenuPrimitive.ContextMenuSubProps;
type ContextMenuSubTriggerProps =
  ContextMenuPrimitive.ContextMenuSubTriggerProps;
type ContextMenuSubContentProps =
  ContextMenuPrimitive.ContextMenuSubContentProps & PresenceAnimationProps;

const Root = createOpenRoot(ContextMenuPrimitive.Root);
const Trigger = ContextMenuPrimitive.Trigger;
const Portal = createPortal(ContextMenuPrimitive.Portal);
const Content = createContent(ContextMenuPrimitive.Content, {
  origin: '--radix-context-menu-content-transform-origin',
  returnFocus: 'previous',
});
const Group = ContextMenuPrimitive.Group;
const Label = ContextMenuPrimitive.Label;
const Item = createItem(ContextMenuPrimitive.Item);
const CheckboxItem = createCheckboxItem(ContextMenuPrimitive.CheckboxItem);
const RadioGroup = createRadioGroup(ContextMenuPrimitive.RadioGroup);
const RadioItem = createRadioItem(ContextMenuPrimitive.RadioItem);
const ItemIndicator = createItemIndicator(ContextMenuPrimitive.ItemIndicator);
const Separator = ContextMenuPrimitive.Separator;
const Arrow = ContextMenuPrimitive.Arrow;
const Sub = createOpenRoot(ContextMenuPrimitive.Sub, { sub: true });
const SubTrigger = createItem(ContextMenuPrimitive.SubTrigger);
const SubContent = createContent(ContextMenuPrimitive.SubContent, {
  origin: '--radix-context-menu-content-transform-origin',
  sub: true,
  returnFocus: 'none',
});

const createContextMenuScope: typeof ContextMenuPrimitive.createContextMenuScope =
  ContextMenuPrimitive.createContextMenuScope;

export {
  Root,
  Trigger,
  Portal,
  Content,
  Group,
  Label,
  Item,
  CheckboxItem,
  RadioGroup,
  RadioItem,
  ItemIndicator,
  Separator,
  Arrow,
  Sub,
  SubTrigger,
  SubContent,
  Root as ContextMenu,
  Trigger as ContextMenuTrigger,
  Portal as ContextMenuPortal,
  Content as ContextMenuContent,
  Group as ContextMenuGroup,
  Label as ContextMenuLabel,
  Item as ContextMenuItem,
  CheckboxItem as ContextMenuCheckboxItem,
  RadioGroup as ContextMenuRadioGroup,
  RadioItem as ContextMenuRadioItem,
  ItemIndicator as ContextMenuItemIndicator,
  Separator as ContextMenuSeparator,
  Arrow as ContextMenuArrow,
  Sub as ContextMenuSub,
  SubTrigger as ContextMenuSubTrigger,
  SubContent as ContextMenuSubContent,
  createContextMenuScope,
  type ContextMenuProps,
  type ContextMenuTriggerProps,
  type ContextMenuPortalProps,
  type ContextMenuContentProps,
  type ContextMenuGroupProps,
  type ContextMenuLabelProps,
  type ContextMenuItemProps,
  type ContextMenuCheckboxItemProps,
  type ContextMenuRadioGroupProps,
  type ContextMenuRadioItemProps,
  type ContextMenuItemIndicatorProps,
  type ContextMenuSeparatorProps,
  type ContextMenuArrowProps,
  type ContextMenuSubProps,
  type ContextMenuSubTriggerProps,
  type ContextMenuSubContentProps,
};

'use client';

import * as React from 'react';
import { AnimatePresence, useMotionValue, type Transition } from 'motion/react';

import {
  ReducedMotionConfig,
  useShouldReduceMotion,
  useTempoTransition,
} from './context-menu-animated-motion';
import {
  HIDDEN_SCALE,
  MENU_TRANSITION,
  MORPH_TRANSITION,
  mergeRefs,
} from './context-menu-animated-anchored';
import {
  HighlightScope,
  useItemHighlight,
  withHighlight,
} from './context-menu-animated-item-highlight';
import {
  HandoffNestedContext,
  MenuHandoffContext,
  takeOver,
  useHandoffNested,
  useMenuHandoff,
} from './context-menu-animated-menu-handoff';
import {
  useStaggeredEnter,
  useStaggerOnOpen,
} from './context-menu-animated-stagger';
import {
  CheckRegistryContext,
  ItemCheck,
  usePickHold,
  PickContext,
  useCheckGroup,
  usePicks,
  type CheckGroup,
  type ItemCheckAnimationProps,
  type Picked,
} from './context-menu-animated-item-indicator';
import { MotionSlot, slotChild } from './context-menu-animated-modal-motion';

type PresenceAnimationProps = {
  transition?: Transition;
  exitTransition?: Transition;
};

type IndicatorAnimationProps = ItemCheckAnimationProps;

type MenuState = {
  open: boolean;
  picked?: Picked;
};

const MenuStateContext = React.createContext<MenuState | null>(null);
const PortalForceMountContext = React.createContext(false);

type IndicatorItem = {
  checked: boolean | 'indeterminate';
  kind: 'checkbox' | 'radio';
  group?: CheckGroup;
};

const IndicatorItemContext = React.createContext<IndicatorItem | null>(null);
const RadioGroupContext = React.createContext<{
  value: string | undefined;
  group: CheckGroup;
} | null>(null);

type OpenStateProps = {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
};

function useOpenState({ open, defaultOpen, onOpenChange }: OpenStateProps) {
  const controlled = open !== undefined;
  const [uncontrolled, setUncontrolled] = React.useState(defaultOpen ?? false);
  const value = controlled ? open : uncontrolled;
  const setValue = (next: boolean) => {
    if (!controlled) setUncontrolled(next);
    onOpenChange?.(next);
  };
  return [value, setValue] as const;
}

function useMenuPicks() {
  const { picks, registerCheck, wasPicked } = usePicks();
  const [picked, setPicked] = React.useState<Picked>(false);
  const onOpenChange = (open: boolean) => setPicked(!open && wasPicked());
  const provide = (children: React.ReactNode) => (
    <PickContext value={picks}>
      <CheckRegistryContext value={registerCheck}>
        {children}
      </CheckRegistryContext>
    </PickContext>
  );
  return { picked, onOpenChange, provide };
}

function createOpenRoot<P extends OpenStateProps>(
  RadixRoot: React.ComponentType<P>,
  { sub = false }: { sub?: boolean } = {},
) {
  function OpenRoot(props: P) {
    const parent = React.use(MenuStateContext);
    const picks = useMenuPicks();
    const [open, setOpen] = useOpenState(props);
    const root = (
      <MenuStateContext
        value={{ open, picked: sub ? parent?.picked : picks.picked }}
      >
        <RadixRoot
          {...props}
          open={open}
          onOpenChange={(next: boolean) => {
            if (!sub) picks.onOpenChange(next);
            setOpen(next);
          }}
        />
      </MenuStateContext>
    );
    return sub ? root : picks.provide(root);
  }
  return OpenRoot;
}

type PortalProps = { forceMount?: true; children?: React.ReactNode };

function createPortal<P extends PortalProps>(
  RadixPortal: React.ComponentType<P>,
) {
  function Portal({ forceMount, ...props }: P) {
    return (
      <PortalForceMountContext value={Boolean(forceMount)}>
        <RadixPortal {...(props as P)} forceMount />
      </PortalForceMountContext>
    );
  }
  return Portal;
}

type OutsideEvent = {
  preventDefault: () => void;
  detail?: unknown;
};

type ContentProps = {
  forceMount?: true;
  asChild?: boolean;
  style?: React.CSSProperties;
  children?: React.ReactNode;
  onCloseAutoFocus?: (event: Event) => void;
  onEscapeKeyDown?: (event: KeyboardEvent) => void;
  onPointerDownOutside?: (event: never) => void;
  onFocusOutside?: (event: never) => void;
  onInteractOutside?: (event: never) => void;
};

type ContentOptions = {
  origin: string;
  sub?: boolean;
  returnFocus: 'trigger' | 'previous' | 'none';
  handoff?: boolean;
};

function createContent<P extends ContentProps>(
  RadixContent: React.ComponentType<P>,
  options: ContentOptions,
) {
  function Content({
    forceMount,
    transition,
    exitTransition,
    ...props
  }: P & PresenceAnimationProps) {
    const state = React.use(MenuStateContext);
    const portalForceMount = React.use(PortalForceMountContext);
    if (!state)
      return <RadixContent {...(props as P)} forceMount={forceMount} />;

    const keepMounted = Boolean(forceMount) || portalForceMount;

    return (
      <AnimatePresence>
        {(state.open || keepMounted) && (
          <ReducedMotionConfig>
            <ContentMotion
              {...(props as ContentProps)}
              component={RadixContent as React.ComponentType<ContentProps>}
              options={options}
              keepMounted={keepMounted}
              transition={transition}
              exitTransition={exitTransition}
            />
          </ReducedMotionConfig>
        )}
      </AnimatePresence>
    );
  }
  Content.displayName = RadixContent.displayName;
  return Content;
}

type ContentMotionProps = ContentProps &
  PresenceAnimationProps & {
    component: React.ComponentType<ContentProps>;
    options: ContentOptions;
    keepMounted: boolean;
  };

function ContentMotion({
  component: RadixContent,
  options,
  keepMounted,
  transition,
  exitTransition,
  style,
  asChild,
  children,
  onCloseAutoFocus,
  onEscapeKeyDown,
  onPointerDownOutside,
  onFocusOutside,
  onInteractOutside,
  ...props
}: ContentMotionProps) {
  const { open, picked } = React.use(MenuStateContext)!;
  const reduce = useShouldReduceMotion();
  const ref = React.useRef<HTMLDivElement>(null);
  const previousFocusRef = React.useRef<Element | null>(null);
  const returnedFocusRef = React.useRef(false);

  const enter = useTempoTransition(transition ?? MENU_TRANSITION);
  const quick = useStaggeredEnter(enter);
  const leave = useTempoTransition(
    exitTransition ?? transition ?? MENU_TRANSITION,
  );
  const morph = useTempoTransition(transition ?? MORPH_TRANSITION);
  const hold = usePickHold();
  const hidden = { opacity: 0, scale: reduce ? 1 : HIDDEN_SCALE.menu };
  const opacity = useMotionValue(hidden.opacity);
  const scale = useMotionValue(hidden.scale);
  const handoff = useMenuHandoff(
    options.handoff ? React.use(MenuHandoffContext) : null,
    {
      nodeRef: ref,
      open,
      transition: morph,
      reduce,
      onDrop: () => {
        for (const value of [opacity, scale])
          (
            value.animation as { complete?: () => void } | undefined
          )?.complete?.();
      },
    },
  );
  useHandoffNested(ref, Boolean(options.sub));
  useStaggerOnOpen(ref, open, { skip: Boolean(handoff.from) });
  const exit: Transition = handoff.dropped
    ? { duration: 0 }
    : picked && !reduce
      ? {
          ...leave,
          delay: ((leave as { delay?: number }).delay ?? 0) + hold(picked),
        }
      : leave;

  const [settledClosed, setSettledClosed] = React.useState(!open);
  if (open && settledClosed) setSettledClosed(false);
  const openRef = React.useRef(open);
  React.useLayoutEffect(() => {
    openRef.current = open;
  });
  const openedAtRef = React.useRef(-Infinity);
  const guard =
    <E extends OutsideEvent>(handler?: (event: E) => void) =>
    (event: E) => {
      handler?.(event);
      const cause = (event.detail as { originalEvent?: Event } | undefined)
        ?.originalEvent;
      if (!openRef.current || (cause && cause.timeStamp < openedAtRef.current))
        event.preventDefault();
    };

  React.useLayoutEffect(() => {
    if (!open) return;
    openedAtRef.current = performance.now();
    previousFocusRef.current = ref.current?.ownerDocument.activeElement ?? null;
    returnedFocusRef.current = false;
  }, [open]);

  React.useEffect(() => {
    const node = ref.current;
    if (open || !node) return;
    const doc = node.ownerDocument;
    if (options.returnFocus === 'none' || onCloseAutoFocus) return;
    if (!node.contains(doc.activeElement)) return;
    const target =
      options.returnFocus === 'trigger'
        ? doc.getElementById(node.getAttribute('aria-labelledby') ?? '')
        : previousFocusRef.current;
    if (target instanceof HTMLElement) {
      target.focus({ preventScroll: true });
      returnedFocusRef.current = true;
    }
  }, [open, onCloseAutoFocus, options.returnFocus]);

  const slot = slotChild(asChild, children);
  return (
    <RadixContent
      {...props}
      forceMount
      asChild
      onEscapeKeyDown={guard(onEscapeKeyDown)}
      onPointerDownOutside={guard(onPointerDownOutside)}
      onFocusOutside={guard(onFocusOutside)}
      onInteractOutside={guard(onInteractOutside)}
      onCloseAutoFocus={(event: Event) => {
        onCloseAutoFocus?.(event);
        if (returnedFocusRef.current) event.preventDefault();
      }}
    >
      <MotionSlot
        element={slot.element}
        ref={ref}
        initial={
          handoff.from ? { opacity: handoff.from.opacity, scale: 1 } : hidden
        }
        animate={
          open
            ? handoff.from
              ? takeOver(handoff.from, enter)
              : { opacity: 1, scale: 1, transition: quick }
            : { ...hidden, transition: exit }
        }
        exit={{ ...hidden, transition: exit }}
        onAnimationComplete={() => {
          if (!openRef.current && keepMounted) setSettledClosed(true);
        }}
        style={{
          opacity,
          scale,
          transformOrigin: `var(${options.origin})`,
          isolation: 'isolate',
          ...(keepMounted && settledClosed && !open
            ? { visibility: 'hidden' as const }
            : null),
          ...(open ? null : { pointerEvents: 'none' as const }),
          ...style,
        }}
      >
        {options.sub ? (
          children
        ) : (
          <HandoffNestedContext value={options.handoff ? handoff.entry : null}>
            <HighlightScope open={open}>{slot.inner}</HighlightScope>
          </HandoffNestedContext>
        )}
      </MotionSlot>
    </RadixContent>
  );
}

type ItemProps = {
  asChild?: boolean;
  disabled?: boolean;
  children?: React.ReactNode;
  ref?: React.Ref<HTMLDivElement>;
};

type SelectableItemProps = ItemProps & { onSelect?: (event: Event) => void };

function HighlightedItem<P extends ItemProps>({
  component: RadixItem,
  props: { asChild, disabled, children, ref, ...props },
}: {
  component: React.ComponentType<P>;
  props: P;
}) {
  const { ref: highlightRef, highlight } = useItemHighlight(disabled);
  const mergedRef = React.useMemo(
    () => mergeRefs(ref, highlightRef),
    [ref, highlightRef],
  );
  return (
    <RadixItem
      {...(props as P)}
      ref={mergedRef}
      asChild={asChild}
      disabled={disabled}
    >
      {withHighlight(children, highlight, asChild)}
    </RadixItem>
  );
}

function createItem<P extends ItemProps>(RadixItem: React.ComponentType<P>) {
  function Item(props: P) {
    return <HighlightedItem component={RadixItem} props={props} />;
  }
  Item.displayName = RadixItem.displayName;
  return Item;
}

type CheckboxItemProps = SelectableItemProps & {
  checked?: boolean | 'indeterminate';
};

function useMarkPick(
  onSelect: ((event: Event) => void) | undefined,
  moves: (item: Element | null) => Picked,
) {
  const picks = React.use(PickContext);
  return (event: Event) => {
    onSelect?.(event);
    if (event.defaultPrevented) return;
    const look = moves(event.currentTarget as Element | null);
    if (look) picks?.markPick(look);
  };
}

function createCheckboxItem<P extends CheckboxItemProps>(
  RadixCheckboxItem: React.ComponentType<P>,
) {
  function CheckboxItem(props: P) {
    const picks = React.use(PickContext);
    const onSelect = useMarkPick(
      props.onSelect,
      (item) => picks?.checkOf(item) ?? false,
    );
    return (
      <IndicatorItemContext
        value={{ checked: props.checked ?? false, kind: 'checkbox' }}
      >
        <HighlightedItem
          component={RadixCheckboxItem}
          props={{ ...props, onSelect }}
        />
      </IndicatorItemContext>
    );
  }
  CheckboxItem.displayName = RadixCheckboxItem.displayName;
  return CheckboxItem;
}

function createRadioGroup<P extends { value?: string }>(
  RadixRadioGroup: React.ComponentType<P>,
) {
  function RadioGroup(props: P) {
    const group = useCheckGroup();
    return (
      <RadioGroupContext value={{ value: props.value, group }}>
        <RadixRadioGroup {...props} />
      </RadioGroupContext>
    );
  }
  RadioGroup.displayName = RadixRadioGroup.displayName;
  return RadioGroup;
}

function createRadioItem<P extends SelectableItemProps & { value: string }>(
  RadixRadioItem: React.ComponentType<P>,
) {
  function RadioItem(props: P) {
    const group = React.use(RadioGroupContext);
    const picks = React.use(PickContext);
    const onSelect = useMarkPick(
      props.onSelect,
      (item) =>
        item?.getAttribute('data-state') !== 'checked' &&
        (picks?.checkOf(item) ?? false),
    );
    return (
      <IndicatorItemContext
        value={
          group
            ? {
                checked: group.value === props.value,
                kind: 'radio',
                group: group.group,
              }
            : null
        }
      >
        <HighlightedItem
          component={RadixRadioItem}
          props={{ ...props, onSelect }}
        />
      </IndicatorItemContext>
    );
  }
  RadioItem.displayName = RadixRadioItem.displayName;
  return RadioItem;
}

type ItemIndicatorProps = {
  forceMount?: true;
  asChild?: boolean;
  children?: React.ReactNode;
};

function createItemIndicator<P extends ItemIndicatorProps>(
  RadixItemIndicator: React.ComponentType<P>,
) {
  function ItemIndicator({
    animation,
    transition,
    forceMount,
    children,
    ...props
  }: P & IndicatorAnimationProps) {
    const item = React.use(IndicatorItemContext);
    if (!item) {
      return (
        <RadixItemIndicator {...(props as P)} forceMount={forceMount}>
          {children}
        </RadixItemIndicator>
      );
    }

    return (
      <RadixItemIndicator {...(props as P)} forceMount asChild>
        <ItemCheck
          multiple={item.kind === 'checkbox'}
          group={item.group ?? null}
          checked={item.checked !== false}
          indeterminate={item.checked === 'indeterminate'}
          animation={animation}
          transition={transition}
        >
          {children}
        </ItemCheck>
      </RadixItemIndicator>
    );
  }
  ItemIndicator.displayName = RadixItemIndicator.displayName;
  return ItemIndicator;
}

export {
  MenuStateContext,
  useMenuPicks,
  createOpenRoot,
  createPortal,
  createContent,
  createItem,
  createCheckboxItem,
  createRadioGroup,
  createRadioItem,
  createItemIndicator,
  type MenuState,
  type PresenceAnimationProps,
  type IndicatorAnimationProps,
};

'use client';

import * as React from 'react';
import {
  createGeneratorEasing,
  generateLinearEasing,
  MotionConfig,
  MotionConfigContext,
  spring as springGenerator,
  type Transition,
} from 'motion/react';

const ease = {
  out: [0.23, 1, 0.32, 1],
  soft: [0.215, 0.61, 0.355, 1],
  draw: [0, 0, 0.58, 1],
  inOut: [0.77, 0, 0.175, 1],
  away: [0.33, 0.17, 0.67, 0.5],
  in: [0.4, 0, 1, 1],
  drawer: [0.34, 1.2, 0.64, 1],
  arrive: [0.11, 0, 0.5, 0],
  color: [0.25, 0.1, 0.25, 1],
  leave: [0, 0, 0.58, 1],
  enter: [0.25, 0.1, 0.35, 1],
  resize: [0.4, 0, 0.1, 1],
  fill: [0.4, 0, 0.2, 1],
} as const;

const spring = {
  press: { type: 'spring', stiffness: 550, damping: 30, restSpeed: 10 },
  pop: { type: 'spring', stiffness: 400, damping: 29 },
  tooltip: { type: 'spring', stiffness: 400, damping: 31 },
  dialog: { type: 'spring', stiffness: 150, damping: 25 },
  toast: { type: 'spring', stiffness: 280, damping: 24 },
  selection: { type: 'spring', stiffness: 300, damping: 30 },
  highlight: { type: 'spring', stiffness: 500, damping: 40 },
  reflow: { type: 'spring', stiffness: 500, damping: 40 },
  handoff: { type: 'spring', stiffness: 450, damping: 43 },
  morph: { type: 'spring', stiffness: 660, damping: 52 },
  height: {
    type: 'spring',
    stiffness: 300,
    damping: 30,
    bounce: 0,
    restDelta: 0.01,
  },
  slide: { type: 'spring', stiffness: 300, damping: 35, restDelta: 0.01 },
  thumb: { type: 'spring', stiffness: 300, damping: 25 },
  slider: { type: 'spring', stiffness: 400, damping: 32 },
  bounce: { type: 'spring', stiffness: 200, damping: 16 },
  glyph: { type: 'spring', stiffness: 500, damping: 45 },
  checkPop: { type: 'spring', stiffness: 500, damping: 24 },
  entrance: { type: 'spring', stiffness: 200, damping: 20 },
  progress: {
    type: 'spring',
    stiffness: 300,
    damping: 35,
    restDelta: 0.01,
    restSpeed: 0.1,
  },
  number: { type: 'spring', stiffness: 90, damping: 50 },
} as const satisfies Record<string, Transition>;

const transition = {
  menu: { duration: 0.22, ease: ease.soft },
  overlay: { duration: 0.4, ease: ease.soft },
  dialogFade: { duration: 0.4, ease: ease.soft },
  fade: { duration: 0.2, ease: ease.out },
  color: { duration: 0.2, ease: ease.color },
  reveal: { duration: 0.3, ease: ease.out },
  disclosure: { duration: 0.35, ease: ease.soft },
  panelOut: { duration: 0.15, ease: ease.leave },
  panelIn: { duration: 0.3, ease: ease.enter },
  tooltipIn: { duration: 0.34, ease: ease.enter },
  tooltipOut: { duration: 0.13, ease: ease.leave },
  panelHeight: { duration: 0.45, ease: ease.resize },
  check: { duration: 0.3, delay: 0.2, ease: ease.draw },
  uncheck: { duration: 0.3, ease: ease.draw },
  fill: { duration: 0.3, ease: ease.fill },
  popOut: { duration: 0.15, ease: ease.out },
  swap: { duration: 0.15, ease: ease.out },
  spin: { duration: 0.3, ease: ease.out },
  handoffOut: { duration: 0.22, ease: ease.soft },
  handoffIn: { duration: 0.26, ease: ease.arrive },
  dismiss: { duration: 0.2, ease: ease.away },
  shake: { duration: 0.4, ease: ease.inOut },
  drawerOut: { duration: 0.16, ease: ease.in },
  drawer: { duration: 0.4, ease: ease.drawer },
  sheet: { duration: 0.4, ease: ease.soft },
  collapse: { duration: 0.28, ease: ease.inOut },
  collapseLabel: { duration: 0.14, ease: ease.out },
  instant: { duration: 0 },
} as const satisfies Record<string, Transition>;

const scale = {
  press: 0.97,
  choice: 0.985,
  tooltip: 0.7,
  popover: 0.8,
  menu: 0.9,
  dialog: 0.8,
  icon: 0.5,
  toast: 0.96,
  fill: 0.7,
  action: 0.9,
} as const;

const blur = {
  icon: 'blur(2px)',
  tooltip: 'blur(6px)',
  disclosure: 'blur(2px)',
  surface: 'blur(4px)',
  panel: 'blur(5px)',
} as const;

const rotate = {
  icon: 90,
} as const;

const shift = {
  handoff: 6,
  navigation: 24,
  tabs: 12,
  step: 24,
  tooltip: 40,
  shake: 3,
} as const;

const stagger: { readonly stack: number } = {
  stack: 0.03,
};

function createMotionTokens(tempo = 1) {
  const pace = <T extends Record<string, Transition>>(set: T): T =>
    tempo === 1
      ? set
      : (Object.fromEntries(
          Object.entries(set).map(([role, value]) => [
            role,
            scaleTransition(value, tempo),
          ]),
        ) as T);

  return {
    tempo,
    ease,
    scale,
    blur,
    rotate,
    shift,
    stagger:
      tempo === 1
        ? stagger
        : (Object.fromEntries(
            Object.entries(stagger).map(([role, delay]) => [
              role,
              delay * tempo,
            ]),
          ) as typeof stagger),
    spring: pace(spring),
    transition: pace(transition),
  } as const;
}

type MotionTokens = ReturnType<typeof createMotionTokens>;

const motionTokens: MotionTokens = createMotionTokens();

const MotionTokensContext = React.createContext<MotionTokens>(motionTokens);

const TIME_KEYS = [
  'duration',
  'visualDuration',
  'delay',
  'repeatDelay',
  'delayChildren',
];

function scaleTransition<T extends Transition | undefined>(
  transition: T,
  tempo: number,
): T {
  if (!transition || tempo === 1 || typeof transition !== 'object')
    return transition;
  const scaled: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(transition)) {
    if (typeof value === 'number' && TIME_KEYS.includes(key))
      scaled[key] = value * tempo;
    else if (typeof value === 'number' && key === 'stiffness')
      scaled[key] = value / (tempo * tempo);
    else if (typeof value === 'number' && key === 'damping')
      scaled[key] = value / tempo;
    else if (value && typeof value === 'object' && !Array.isArray(value))
      scaled[key] = scaleTransition(value as Transition, tempo);
    else scaled[key] = value;
  }
  return scaled as T;
}

function useTempoTransition<T extends Transition | undefined>(
  transition: T,
): T {
  const { tempo } = React.use(MotionTokensContext);
  return scaleTransition(transition, tempo);
}

function useMotionTokens(): MotionTokens {
  return React.use(MotionTokensContext);
}

type CheckAnimation = 'draw' | 'pop';

const CheckAnimationContext = React.createContext<CheckAnimation>('draw');

function useCheckAnimation(own?: CheckAnimation): CheckAnimation {
  const inherited = React.use(CheckAnimationContext);
  return own ?? inherited;
}

type CssTiming = { duration: number; easing: string };

const CSS_EASINGS: Record<string, string> = {
  linear: 'linear',
  easeIn: 'cubic-bezier(0.42, 0, 1, 1)',
  easeOut: 'cubic-bezier(0, 0, 0.58, 1)',
  easeInOut: 'cubic-bezier(0.42, 0, 0.58, 1)',
  circIn: 'cubic-bezier(0, 0.65, 0.55, 1)',
  circOut: 'cubic-bezier(0.55, 0, 1, 0.45)',
  backIn: 'cubic-bezier(0.31, 0.01, 0.66, -0.59)',
  backOut: 'cubic-bezier(0.33, 1.53, 0.69, 0.99)',
};

const SPRING_KEYS = [
  'stiffness',
  'damping',
  'mass',
  'bounce',
  'visualDuration',
];

function toCssEase(curve: unknown): string {
  if (
    Array.isArray(curve) &&
    curve.length === 4 &&
    curve.every(Number.isFinite)
  )
    return `cubic-bezier(${curve.join(', ')})`;
  if (typeof curve === 'string') return CSS_EASINGS[curve] ?? 'ease';
  return CSS_EASINGS.easeInOut!;
}

function toCssTiming(motionTransition: Transition): CssTiming {
  const options = motionTransition as Record<string, unknown>;
  const isSpring =
    options.type === 'spring' || SPRING_KEYS.some((key) => key in options);

  if (isSpring) {
    const springOptions =
      typeof options.duration === 'number'
        ? { ...options, duration: options.duration * 1000 }
        : options;
    const { duration, ease: curve } = createGeneratorEasing(
      springOptions,
      100,
      springGenerator,
    );
    const ms = Math.round(duration * 1000);
    return { duration: ms, easing: generateLinearEasing(curve, ms) };
  }

  const seconds = typeof options.duration === 'number' ? options.duration : 0.3;
  return {
    duration: Math.round(seconds * 1000),
    easing: toCssEase(options.ease),
  };
}

type ReducedMotion = 'user' | 'never' | 'always';

const ReducedMotionContext = React.createContext<ReducedMotion>('user');

function useReducedMotionSetting(): ReducedMotion {
  const own = React.use(ReducedMotionContext);
  const { reducedMotion } = React.use(MotionConfigContext);
  return reducedMotion === 'always' ? 'always' : own;
}

type ReducedMotionConfigProps = {
  children: React.ReactNode;
  remount?: boolean;
};

function ReducedMotionConfig({ children, remount }: ReducedMotionConfigProps) {
  const reducedMotion = useReducedMotionSetting();

  return (
    <MotionConfig reducedMotion={reducedMotion}>
      {remount ? <RemountOnReduce>{children}</RemountOnReduce> : children}
    </MotionConfig>
  );
}

function RemountOnReduce({ children }: { children: React.ReactNode }) {
  const reduce = useShouldReduceMotion();
  return (
    <React.Fragment key={reduce ? 'reduce' : 'full'}>{children}</React.Fragment>
  );
}

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)';

function subscribeToReducedMotion(onChange: () => void) {
  const mql = window.matchMedia(REDUCED_MOTION_QUERY);
  mql.addEventListener('change', onChange);
  return () => mql.removeEventListener('change', onChange);
}

function useShouldReduceMotion() {
  const reducedMotion = useReducedMotionSetting();
  const prefersReduced = React.useSyncExternalStore(
    subscribeToReducedMotion,
    () => window.matchMedia(REDUCED_MOTION_QUERY).matches,
    () => false,
  );

  if (reducedMotion === 'never') return false;
  return reducedMotion === 'always' || prefersReduced;
}

