  type AnchoredAnimationProps,
  type AnchoredMotionProps,
};

'use client';

import * as React from 'react';
import {
  createGeneratorEasing,
  generateLinearEasing,
  spring as springGenerator,
  type Transition,
} from 'motion/react';

import {
  motionTokens,
  toCssTiming,
  useShouldReduceMotion,
  useTempoTransition,
} from './context-menu-animated-motion';
import { layoutScale } from './context-menu-animated-layout-scale';
import { staggerLeft } from './context-menu-animated-stagger';

const HIGHLIGHT_TRANSITION = motionTokens.spring.highlight;
const FADE_TRANSITION = motionTokens.transition.color;
const RESUME_TRANSITION = motionTokens.transition.fade;

type Surface = {
  backgroundColor: string;
  backgroundImage: string;
  borderRadius: string;
};

type Offset = {
  x: number;
  y: number;
  scaleX: number;
  scaleY: number;
};

type Glide = {
  animation: Animation;
  ease: (progress: number) => number;
  duration: number;
  from: Offset;
};

type SurfaceHandle = {
  id: string;
  element: HTMLElement;
  item: HTMLElement;
  glide: Glide | null;
};

type Leaving = { id: string; to: HTMLElement | null; key: number };

type HighlightScopeValue = {
  activeId: string | null;
  leaving: readonly Leaving[];
  slot: string;
  activate: (id: string, item: HTMLElement) => void;
  light: (id: string, item: HTMLElement) => void;
  unlight: (id: string) => void;
  left: (id: string) => void;
  handOff: (item: HTMLElement, reduce: boolean, fading?: boolean) => Start;
  register: (handle: SurfaceHandle) => () => void;
  carry: (handle: SurfaceHandle) => () => void;
  gone: (opacity: number) => void;
  paint: (surface: Surface) => Surface;
};

const HighlightScopeContext = React.createContext<HighlightScopeValue | null>(
  null,
);

const TriggerScopeContext = React.createContext<HighlightScopeValue | null>(
  null,
);

type HighlightScopeProps = {
  open: boolean;
  shared?: boolean;
  children?: React.ReactNode;
};

function HighlightScope({ shared, ...props }: HighlightScopeProps) {
  const parent = React.use(HighlightScopeContext);
  if (shared && parent) return props.children;
  return (
    <OwnHighlightScope
      {...props}
      context={HighlightScopeContext}
      slot="item-highlight"
    />
  );
}

function TriggerHighlightScope({ children }: { children?: React.ReactNode }) {
  return (
    <OwnHighlightScope
      open
      context={TriggerScopeContext}
      slot="trigger-highlight"
    >
      {children}
    </OwnHighlightScope>
  );
}

function OwnHighlightScope({
  open,
  context: Context,
  slot,
  children,
}: Omit<HighlightScopeProps, 'shared'> & {
  context: React.Context<HighlightScopeValue | null>;
  slot: string;
}) {
  const [activeId, setActiveId] = React.useState<string | null>(null);
  const [leaving, setLeaving] = React.useState<readonly Leaving[]>([]);
  const surfaceRef = React.useRef<SurfaceHandle | null>(null);
  const carriersRef = React.useRef(new Set<SurfaceHandle>());
  const keyRef = React.useRef(0);
  const paintRef = React.useRef<Surface | null>(null);
  const litRef = React.useRef(new Map<string, HTMLElement>());
  const activeRef = React.useRef<string | null>(null);
  React.useLayoutEffect(() => {
    activeRef.current = activeId;
  }, [activeId]);
  const [wasOpen, setWasOpen] = React.useState(open);
  if (wasOpen !== open) {
    setWasOpen(open);
    if (open) {
      setActiveId(null);
      setLeaving([]);
    }
  }

  const activate = React.useCallback((id: string, item: HTMLElement) => {
    const previous = surfaceRef.current;
    activeRef.current = id;
    setActiveId(id);
    const moves =
      previous && previous.id !== id && previous.element.isConnected
        ? previous
        : null;
    const cross = moves !== null && crossesClip(moves.item, item);
    const key = (keyRef.current += 1);
    setLeaving((list) => {
      const rest = without(list, id).filter((other) => other.to !== null);
      if (!moves || (!cross && rest.length === 0)) return rest;
      const along = rest.map((other) => ({ ...other, to: item, key }));
      return cross
        ? [...without(along, moves.id), { id: moves.id, to: item, key }]
        : along;
    });
  }, []);
  const left = React.useCallback(
    (id: string) => setLeaving((list) => without(list, id)),
    [],
  );
  const light = React.useCallback(
    (id: string, item: HTMLElement) => {
      litRef.current.delete(id);
      litRef.current.set(id, item);
      activate(id, item);
    },
    [activate],
  );
  const unlight = React.useCallback(
    (id: string) => {
      const lit = litRef.current;
      const item = lit.get(id);
      if (!lit.delete(id) || activeRef.current !== id) return;
      const next = [...lit].at(-1);
      if (next) {
        activate(...next);
        return;
      }
      activeRef.current = null;
      setActiveId(null);
      const key = (keyRef.current += 1);
      // The copies carrying it there end in the one fading out
      setLeaving((list) => [
        ...without(list, id).filter((other) => other.to !== item),
        { id, to: null, key },
      ]);
    },
    [activate],
  );
  const goneRef = React.useRef<{ opacity: number; at: number } | null>(null);
  const handOffFrom = React.useCallback(
    (item: HTMLElement, reduce: boolean, fading = false) => {
      const from = fading
        ? mostShown(surfaceRef.current, carriersRef.current)
        : surfaceRef.current;
      const start = handOff(from, item, reduce);
      const gone = goneRef.current;
      if (
        !from?.element.isConnected &&
        gone &&
        performance.now() - gone.at < 120
      )
        return { ...start, opacity: gone.opacity, fresh: false };
      return start;
    },
    [],
  );
  const gone = React.useCallback((opacity: number) => {
    goneRef.current = { opacity, at: performance.now() };
  }, []);
  const carry = React.useCallback((handle: SurfaceHandle) => {
    carriersRef.current.add(handle);
    return () => {
      carriersRef.current.delete(handle);
    };
  }, []);
  const register = React.useCallback((handle: SurfaceHandle) => {
    surfaceRef.current = handle;
    return () => {
      if (surfaceRef.current === handle) surfaceRef.current = null;
    };
  }, []);
  const paint = React.useCallback((surface: Surface) => {
    if (isBare(surface)) return paintRef.current ?? surface;
    paintRef.current = surface;
    return surface;
  }, []);

  const value = React.useMemo(
    () => ({
      activeId,
      leaving,
      slot,
      activate,
      light,
      unlight,
      left,
      handOff: handOffFrom,
      register,
      carry,
      gone,
      paint,
    }),
    [
      activeId,
      leaving,
      slot,
      activate,
      light,
      unlight,
      left,
      handOffFrom,
      register,
      carry,
      gone,
      paint,
    ],
  );

  return <Context value={value}>{children}</Context>;
}

const SURFACE_PROPERTIES = ['background-color', 'background-image'] as const;
type SavedStyle = [property: string, value: string, priority: string][];
const savedStyles = new WeakMap<HTMLElement, SavedStyle>();

function save(node: HTMLElement, properties: readonly string[]): SavedStyle {
  return properties.map((property) => [
    property,
    node.style.getPropertyValue(property),
    node.style.getPropertyPriority(property),
  ]);
}

function restore(node: HTMLElement, saved: SavedStyle) {
  for (const [property, value, priority] of saved) {
    if (value) node.style.setProperty(property, value, priority);
    else node.style.removeProperty(property);
  }
}

function clearOwnSurface(node: HTMLElement, clear: boolean) {
  const saved = savedStyles.get(node);
  if (clear && !saved) {
    savedStyles.set(node, save(node, SURFACE_PROPERTIES));
    node.style.setProperty('background-color', 'transparent', 'important');
    node.style.setProperty('background-image', 'none', 'important');
  } else if (!clear && saved) {
    savedStyles.delete(node);
    restore(node, saved);
  }
}

const isBare = ({ backgroundColor, backgroundImage }: Surface) =>
  backgroundImage === 'none' &&
  (backgroundColor === 'transparent' ||
    /^rgba\(.*,\s*0\)$/.test(backgroundColor));

/** A surface painted in the color behind it shows nothing: a highlight may glide over it. */
function blendsIn(node: HTMLElement, surface: Surface) {
  if (surface.backgroundImage !== 'none' || isBare(surface)) return false;
  for (let el = node.parentElement; el; el = el.parentElement) {
    const style = getComputedStyle(el);
    if (style.backgroundImage !== 'none') return false;
    const backdrop = { ...surface, backgroundColor: style.backgroundColor };
    if (!isBare(backdrop))
      return style.backgroundColor === surface.backgroundColor;
  }
  return false;
}

function readSurface(node: HTMLElement): Surface {
  const cleared = savedStyles.get(node);
  // Only a transition on the background has to stop for it to be read: taking
  // the others off would cancel them (a sidebar button's width as it folds)
  const stops = /all|background/.test(
    getComputedStyle(node).transitionProperty,
  );
  const transition = stops ? save(node, ['transition']) : null;
  if (stops) node.style.setProperty('transition', 'none', 'important');
  if (cleared) restore(node, cleared);
  const style = getComputedStyle(node);
  const surface = {
    backgroundColor: style.backgroundColor,
    backgroundImage: style.backgroundImage,
    borderRadius: style.borderRadius,
  };
  if (cleared) {
    node.style.setProperty('background-color', 'transparent', 'important');
    node.style.setProperty('background-image', 'none', 'important');
  }
  void getComputedStyle(node).backgroundColor;
  if (transition) restore(node, transition);
  return surface;
}

const isExpanded = (node: HTMLElement) =>
  node.getAttribute('aria-expanded') === 'true';

const without = (list: readonly Leaving[], id: string) =>
  list.some((other) => other.id === id)
    ? list.filter((other) => other.id !== id)
    : list;

function clipperOf(item: HTMLElement) {
  const body = item.ownerDocument.body;
  for (let el = item.parentElement; el && el !== body; el = el.parentElement) {
    const { overflowX, overflowY } = getComputedStyle(el);
    if (overflowX !== 'visible' || overflowY !== 'visible') return el;
  }
  return null;
}

const crossesClip = (from: HTMLElement, to: HTMLElement) =>
  clipperOf(from) !== clipperOf(to);

// Out of a clipped box into the one around it, the one leaving is cut on the
// way: it fades out under the one coming in, whole at once. Otherwise the one
// coming in fades in over the one leaving.
const comesOut = (from: HTMLElement, to: HTMLElement) => {
  const inner = clipperOf(from);
  const outer = clipperOf(to);
  return !!inner && !inner.contains(to) && (!outer || outer.contains(from));
};

type ItemHighlight = {
  ref: (node: HTMLElement | null) => void;
  highlight: React.ReactNode;
};

type ItemHighlightOptions = {
  attribute?: string;
  followFocus?: boolean;
};

type TriggerHighlightOptions = {
  beside?: boolean;
};

function useItemHighlight(
  disabled?: boolean,
  {
    attribute = 'data-highlighted',
    followFocus = false,
  }: ItemHighlightOptions = {},
): ItemHighlight {
  return useHighlightIn(
    React.use(HighlightScopeContext),
    disabled,
    attribute,
    false,
    followFocus,
  );
}

function useTriggerHighlight(
  disabled?: boolean,
  { beside = false }: TriggerHighlightOptions = {},
): ItemHighlight {
  return useHighlightIn(React.use(TriggerScopeContext), disabled, null, beside);
}

const samePaint = (a: Surface | null, b: Surface) =>
  a !== null &&
  a.backgroundColor === b.backgroundColor &&
  a.backgroundImage === b.backgroundImage &&
  a.borderRadius === b.borderRadius;

const TRIGGER_ATTRIBUTES = [
  'aria-expanded',
  'data-state',
  'data-highlighted',
  'data-popup-open',
  'data-pressed',
  'data-disabled',
];

function useHighlightIn(
  scope: HighlightScopeValue | null,
  disabled: boolean | undefined,
  attribute: string | null,
  beside = false,
  followFocus = false,
): ItemHighlight {
  const id = React.useId();
  const [node, setNode] = React.useState<HTMLElement | null>(null);
  const [surface, setSurface] = React.useState<Surface | null>(null);
  const paint = scope?.paint;
  const light = scope?.light;
  const unlight = scope?.unlight;
  const ref = React.useCallback((element: HTMLElement | null) => {
    if (element)
      setNode((current) => (current === element ? current : element));
  }, []);

  React.useLayoutEffect(() => {
    if (attribute !== null || !light || !unlight || !node) return;
    if (!beside && getComputedStyle(node).position === 'static')
      node.style.setProperty('position', 'relative');
    let hovered = false;
    let lit = false;
    let frame = 0;
    const sync = () => {
      const interactive =
        !disabled && (hovered || isExpanded(node) || node.matches(':focus'));
      if (interactive) clearOwnSurface(node, true);
      const surface = interactive ? readSurface(node) : null;
      const now = surface !== null && !isBare(surface);
      if (surface && now)
        setSurface((current) =>
          samePaint(current, surface) ? current : surface,
        );
      clearOwnSurface(
        node,
        now || (!interactive && blendsIn(node, readSurface(node))),
      );
      if (now === lit) return;
      lit = now;
      if (now) light(id, node);
      else unlight(id);
    };
    const enter = () => {
      hovered = true;
      sync();
      cancelAnimationFrame(frame);
      frame = requestAnimationFrame(sync);
    };
    const leave = () => {
      hovered = false;
      cancelAnimationFrame(frame);
      sync();
    };
    sync();
    const observer = new MutationObserver(sync);
    observer.observe(node, {
      attributes: true,
      attributeFilter: TRIGGER_ATTRIBUTES,
    });
    node.addEventListener('pointerenter', enter);
    node.addEventListener('pointerleave', leave);
    node.addEventListener('focus', sync);
    node.addEventListener('blur', sync);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
      node.removeEventListener('pointerenter', enter);
      node.removeEventListener('pointerleave', leave);
      node.removeEventListener('focus', sync);
      node.removeEventListener('blur', sync);
      clearOwnSurface(node, false);
      if (lit) unlight(id);
    };
  }, [attribute, light, unlight, node, id, disabled, beside]);

  React.useLayoutEffect(() => {
    if (attribute === null || !light || !unlight || !paint || !node) return;
    if (getComputedStyle(node).position === 'static')
      node.style.setProperty('position', 'relative');

    const clear = () =>
      clearOwnSurface(
        node,
        node.hasAttribute(attribute) ||
          isExpanded(node) ||
          node.matches(':focus'),
      );
    const sync = () => {
      if (node.hasAttribute(attribute)) {
        setSurface(paint(readSurface(node)));
        light(id, node);
      } else if (followFocus) unlight(id);
      clear();
    };
    const focus = () => {
      if (node.hasAttribute(attribute)) setSurface(paint(readSurface(node)));
      clear();
    };
    sync();
    const observer = new MutationObserver(sync);
    observer.observe(node, {
      attributes: true,
      attributeFilter: [attribute, 'aria-expanded'],
    });
    node.addEventListener('focus', focus);
    node.addEventListener('blur', clear);
    return () => {
      observer.disconnect();
      node.removeEventListener('focus', focus);
      node.removeEventListener('blur', clear);
      clearOwnSurface(node, false);
    };
  }, [light, unlight, paint, node, id, attribute, followFocus]);

  const active = scope?.activeId === id && !disabled;
  const leaving =
    (!disabled && scope?.leaving.find((other) => other.id === id)) || null;

  return {
    ref,
    highlight: scope ? (
      <HighlightSurface
        id={id}
        surface={surface}
        active={active}
        leaving={leaving}
        item={node}
        scope={scope}
        beside={beside}
      />
    ) : null,
  };
}

type HighlightSurfaceProps = {
  id: string;
  surface: Surface | null;
  active: boolean;
  leaving: Leaving | null;
  item: HTMLElement | null;
  scope: HighlightScopeValue;
  beside: boolean;
};

function HighlightSurface({
  id,
  surface,
  active,
  leaving,
  item,
  scope,
  beside,
}: HighlightSurfaceProps) {
  if (!surface || !item) return null;
  return (
    <>
      {active && (
        <SurfaceCopy
          key="active"
          id={id}
          surface={surface}
          item={item}
          scope={scope}
          beside={beside}
        />
      )}
      {leaving && !active && (
        <SurfaceCopy
          key={`leaving-${leaving.key}`}
          id={id}
          surface={surface}
          item={item}
          scope={scope}
          beside={beside}
          leavingTo={leaving.to}
          fadeOut={leaving.to === null}
        />
      )}
    </>
  );
}

function placeOver(element: HTMLElement, item: HTMLElement) {
  const host = element.offsetParent as HTMLElement | null;
  const box = item.getBoundingClientRect();
  const origin = host?.getBoundingClientRect();
  const { x: ratioX, y: ratioY } =
    host && origin ? layoutScale(host, origin) : { x: 1, y: 1 };
  const left = origin
    ? (box.left - origin.left) / ratioX - host!.clientLeft + host!.scrollLeft
    : box.left + window.scrollX;
  const top = origin
    ? (box.top - origin.top) / ratioY - host!.clientTop + host!.scrollTop
    : box.top + window.scrollY;
  element.style.left = `${left}px`;
  element.style.top = `${top}px`;
  element.style.width = `${box.width / ratioX}px`;
  element.style.height = `${box.height / ratioY}px`;
}

function useBesideBox(
  elementRef: React.RefObject<HTMLElement | null>,
  item: HTMLElement,
  beside: boolean,
) {
  React.useLayoutEffect(() => {
    const element = elementRef.current;
    if (!beside || !element) return;
    const place = () => placeOver(element, item);
    place();
    const observer = new ResizeObserver(place);
    observer.observe(item);
    if (element.offsetParent) observer.observe(element.offsetParent);
    return () => observer.disconnect();
  }, [elementRef, item, beside]);
}

type Start = {
  offset: Offset;
  opacity: number;
  color: string | null;
  fresh: boolean;
  velocity: Offset;
  cross: boolean;
  enters: boolean;
};

const IN_PLACE: Offset = { x: 0, y: 0, scaleX: 1, scaleY: 1 };
const STILL: Offset = { x: 0, y: 0, scaleX: 0, scaleY: 0 };

function velocityOf({ animation, ease, duration, from }: Glide): Offset {
  const time = Number(animation.currentTime ?? duration);
  if (!(time < duration)) return STILL;
  const step = 4;
  const before = Math.max(0, time - step);
  const rate =
    (ease(Math.min(1, (before + step) / duration)) - ease(before / duration)) /
    step;
  return {
    x: -from.x * rate,
    y: -from.y * rate,
    scaleX: (1 - from.scaleX) * rate,
    scaleY: (1 - from.scaleY) * rate,
  };
}

// Carried over from another clipped box, the highlight is shown by the copies
// leaving for it while it fades in: it fades out from the one shown most
function mostShown(
  surface: SurfaceHandle | null,
  carriers: Set<SurfaceHandle>,
) {
  let shown = surface?.element.isConnected ? surface : null;
  let most = shown ? Number(getComputedStyle(shown.element).opacity) : 0;
  for (const carrier of carriers) {
    if (!carrier.element.isConnected) continue;
    const opacity = Number(getComputedStyle(carrier.element).opacity);
    if (opacity > most) {
      shown = carrier;
      most = opacity;
    }
  }
  return shown ?? surface;
}

function handOff(
  previous: SurfaceHandle | null,
  item: HTMLElement,
  reduce: boolean,
): Start {
  if (!previous?.element.isConnected)
    return {
      offset: IN_PLACE,
      opacity: 0,
      color: null,
      fresh: true,
      velocity: STILL,
      cross: false,
      enters: false,
    };
  const style = getComputedStyle(previous.element);
  const opacity = Number(style.opacity);
  const color = style.backgroundColor;
  const cross = crossesClip(previous.item, item);
  const enters = cross && !comesOut(previous.item, item);
  const offset = offsetOn(previous.element.getBoundingClientRect(), item);
  if (reduce || !offset)
    return {
      offset: IN_PLACE,
      opacity,
      color,
      fresh: false,
      velocity: STILL,
      cross,
      enters,
    };

  const own = item.getBoundingClientRect();
  const from = previous.item.getBoundingClientRect();
  const velocity = previous.glide ? velocityOf(previous.glide) : STILL;
  return {
    offset,
    opacity,
    color,
    fresh: false,
    velocity: {
      x: velocity.x,
      y: velocity.y,
      scaleX: (velocity.scaleX * from.width) / own.width,
      scaleY: (velocity.scaleY * from.height) / own.height,
    },
    cross,
    enters,
  };
}

function offsetOn(box: DOMRect, item: HTMLElement): Offset | null {
  const own = item.getBoundingClientRect();
  if (!own.width || !own.height) return null;
  const ratioX = own.width / (item.offsetWidth || own.width);
  const ratioY = own.height / (item.offsetHeight || own.height);
  return {
    x: (box.left - own.left) / ratioX,
    y: (box.top - own.top) / ratioY,
    scaleX: box.width / own.width,
    scaleY: box.height / own.height,
  };
}

function initialRate(
  { offset, velocity }: Start,
  to: Offset,
  width: number,
  height: number,
) {
  const way = [
    to.x - offset.x,
    to.y - offset.y,
    (to.scaleX - offset.scaleX) * width,
    (to.scaleY - offset.scaleY) * height,
  ];
  const speed = [
    velocity.x,
    velocity.y,
    velocity.scaleX * width,
    velocity.scaleY * height,
  ];
  const length = way.reduce((sum, d) => sum + d * d, 0);
  if (length < 0.25) return null;
  return way.reduce((sum, d, i) => sum + d * speed[i]!, 0) / length;
}

const toTransform = ({ x, y, scaleX, scaleY }: Offset) =>
  `translate(${x}px, ${y}px) scale(${scaleX}, ${scaleY})`;

type SurfaceCopyProps = {
  id: string;
  surface: Surface;
  item: HTMLElement;
  scope: HighlightScopeValue;
  leavingTo?: HTMLElement | null;
  fadeOut?: boolean;
  beside?: boolean;
};

function SurfaceCopy({
  id,
  surface,
  item,
  scope,
  leavingTo = null,
  fadeOut = false,
  beside = false,
}: SurfaceCopyProps) {
  const reduce = useShouldReduceMotion();
  const glide = useTempoTransition<Transition>(HIGHLIGHT_TRANSITION);
  const fade = useTempoTransition<Transition>(FADE_TRANSITION);
  const resume = useTempoTransition<Transition>(RESUME_TRANSITION);
  const [start] = React.useState(() => scope.handOff(item, reduce, fadeOut));
  const [target] = React.useState(() =>
    leavingTo && !reduce
      ? offsetOn(leavingTo.getBoundingClientRect(), item)
      : null,
  );
  const elementRef = React.useRef<HTMLSpanElement>(null);
  const transitionsRef = React.useRef({ glide, fade, resume });
  const { register, carry, gone, left } = scope;
  useBesideBox(elementRef, item, beside);

  React.useLayoutEffect(() => {
    const element = elementRef.current;
    if (!element) return undefined;
    const animations: Animation[] = [];
    let running: Glide | null = null;
    if (leavingTo && !target) {
      left(id);
      return undefined;
    }

    const to = target ?? IN_PLACE;
    const rate = initialRate(start, to, item.offsetWidth, item.offsetHeight);
    let timing: { duration: number; easing: string } | null = null;
    if (rate !== null) {
      const { ease, duration } = createGeneratorEasing(
        { ...transitionsRef.current.glide, velocity: rate * 1000 * 100 },
        100,
        springGenerator,
      );
      const ms = duration * 1000;
      timing = { duration: ms, easing: generateLinearEasing(ease, ms) };
      const animation = element.animate(
        [
          { transform: toTransform(start.offset) },
          { transform: target ? toTransform(target) : 'none' },
        ],
        { ...timing, fill: target ? 'forwards' : 'auto' },
      );
      animations.push(animation);
      running = { animation, ease, duration: ms, from: start.offset };
    }

    if (target) {
      if (running && comesOut(item, leavingTo!))
        animations.push(
          element.animate([{ opacity: 1 }, { opacity: 0 }], {
            ...timing!,
            fill: 'forwards',
          }),
        );
      if (running)
        running.animation.finished.then(
          () => left(id),
          () => {},
        );
      else left(id);
      const uncarry = carry({ id, element, item, glide: running });
      return () => {
        for (const animation of animations) animation.cancel();
        uncarry();
      };
    }

    // An item still coming in with its list's stagger: its highlight shows once it has landed.
    const landing = staggerLeft(element.parentElement);
    if (fadeOut) {
      const { duration, easing } = toCssTiming(transitionsRef.current.fade);
      const fading = element.animate(
        [{ opacity: start.opacity }, { opacity: 0 }],
        { duration, easing, fill: 'forwards' },
      );
      animations.push(fading);
      fading.finished.then(
        () => left(id),
        () => {},
      );
    } else if (start.enters && timing) {
      animations.push(
        element.animate([{ opacity: 0 }, { opacity: 1 }], timing),
      );
    } else if (start.opacity < 1 || landing > 0) {
      const { duration, easing } = toCssTiming(
        start.fresh || landing > 0
          ? transitionsRef.current.fade
          : transitionsRef.current.resume,
      );
      animations.push(
        element.animate(
          [{ opacity: landing > 0 ? 0 : start.opacity }, { opacity: 1 }],
          { duration, easing, delay: landing, fill: 'backwards' },
        ),
      );
    }

    const color = getComputedStyle(element).backgroundColor;
    if (start.color && start.color !== color && !target) {
      const { duration, easing } = toCssTiming(transitionsRef.current.fade);
      animations.push(
        element.animate(
          [{ backgroundColor: start.color }, { backgroundColor: color }],
          { duration, easing },
        ),
      );
    }

    const unregister = register({ id, element, item, glide: running });
    return () => {
      const opacity = element.isConnected
        ? Number(getComputedStyle(element).opacity)
        : 0;
      for (const animation of animations) animation.cancel();
      unregister();
      gone(opacity);
    };
  }, [
    register,
    carry,
    gone,
    left,
    id,
    item,
    start,
    target,
    leavingTo,
    fadeOut,
  ]);

  const { duration: colorDuration, easing: colorEasing } = toCssTiming(fade);

  return (
    <span
      ref={elementRef}
      aria-hidden
      data-slot={scope.slot}
      data-leaving={leavingTo || fadeOut ? '' : undefined}
      style={{
        position: 'absolute',
        ...(!beside && { inset: 0 }),
        zIndex: -1,
        pointerEvents: 'none',
        transformOrigin: '0 0',
        borderRadius: surface.borderRadius,
        backgroundColor: surface.backgroundColor,
        backgroundImage: surface.backgroundImage,
        transition: `background-color ${colorDuration}ms ${colorEasing}`,
      }}
    />
  );
}

function withHighlight(
  children: React.ReactNode,
  highlight: React.ReactNode,
  asChild?: boolean,
): React.ReactNode {
  if (!highlight) return children;
  if (asChild && React.isValidElement<{ children?: React.ReactNode }>(children))
    return React.cloneElement(
      children,
      undefined,
      <>
        {children.props.children}
        {highlight}
      </>,
    );
  return (
    <>
      {children}
      {highlight}
    </>
  );
}

export {
  HighlightScope,
  TriggerHighlightScope,
  useItemHighlight,
  useTriggerHighlight,
  withHighlight,
  HIGHLIGHT_TRANSITION,
  type ItemHighlight,
  type TriggerHighlightOptions,
};

'use client';

import * as React from 'react';
import type { Transition } from 'motion/react';

import { motionTokens, toCssTiming, useTempoTransition } from './context-menu-animated-motion';
import { carries, curveFrom, velocityOf, type Run } from './context-menu-animated-momentum';

class HandoffEntry {
  node: HTMLElement | null = null;
  open = false;
  openedAt = 0;
  movedOn = false;
  dropped = false;
  pending: HandoffEntry | null = null;
  readonly nested = new Set<HTMLElement>();
  private onDrop = () => {};

  attach(node: HTMLElement | null, onDrop: () => void) {
    this.node = node;
    this.onDrop = onDrop;
  }

  drop() {
    this.dropped = true;
    this.pending = null;
    for (const node of [this.node, ...this.nested]) hide(node);
    this.onDrop();
  }

  reopen() {
    if (!this.dropped) return;
    this.dropped = false;
    show(this.node);
  }

  await(source: HandoffEntry | null) {
    this.pending = source;
  }

  addNested(node: HTMLElement) {
    show(node);
    this.nested.add(node);
    return () => {
      this.nested.delete(node);
    };
  }
}

const hidden = new WeakSet<HTMLElement>();

function hide(node: HTMLElement | null) {
  if (!node) return;
  node.style.visibility = 'hidden';
  hidden.add(node);
}

function show(node: HTMLElement | null) {
  if (!node || !hidden.has(node)) return;
  node.style.visibility = '';
  hidden.delete(node);
}

class HandoffGroup {
  private entries = new Set<HandoffEntry>();
  private clock = 0;

  add(entry: HandoffEntry) {
    this.entries.add(entry);
    return () => {
      this.entries.delete(entry);
    };
  }

  setOpen(entry: HandoffEntry, open: boolean, movedOn: boolean) {
    entry.open = open;
    entry.movedOn = !open && movedOn;
    if (open) entry.openedAt = this.clock += 1;
  }

  source(self: HandoffEntry) {
    let source: HandoffEntry | null = null;
    for (const entry of this.entries) {
      if (entry === self || entry.dropped) continue;
      if (!entry.open && !(entry.movedOn && isShown(entry.node))) continue;
      if (!entry.node?.isConnected) continue;
      if (!source || entry.openedAt > source.openedAt) source = entry;
    }
    const skipped: HandoffEntry[] = [];
    while (
      source?.pending &&
      !source.pending.dropped &&
      source.pending.node?.isConnected
    ) {
      skipped.push(source);
      source = source.pending;
    }
    return source ? { entry: source, skipped } : null;
  }
}

function isShown(node: HTMLElement | null) {
  if (!node?.isConnected) return false;
  const style = getComputedStyle(node);
  return style.visibility !== 'hidden' && Number(style.opacity) > 0.02;
}

function canAnimate() {
  return (
    typeof Element !== 'undefined' &&
    typeof Element.prototype.animate === 'function' &&
    typeof Element.prototype.getAnimations === 'function'
  );
}

const MenuHandoffContext = React.createContext<HandoffGroup | null>(null);

const HandoffNestedContext = React.createContext<HandoffEntry | null>(null);

function useHandoffGroup(): HandoffGroup {
  const [group] = React.useState(() => new HandoffGroup());
  return group;
}

function useHandoffNested(
  nodeRef: React.RefObject<HTMLElement | null>,
  nested: boolean,
) {
  const parent = React.use(HandoffNestedContext);
  React.useLayoutEffect(() => {
    const node = nodeRef.current;
    if (!nested || !parent || !node) return;
    return parent.addNested(node);
  }, [nested, parent, nodeRef]);
}

type Opening = {
  open: boolean;
  source: HandoffEntry | null;
  skipped: HandoffEntry[];
  opacity: number;
};

const UNIQUE_ATTRIBUTES = [
  'id',
  'data-testid',
  'tabindex',
  'autofocus',
  'data-radix-collection-item',
];

const ANIMATED_PROPERTIES = [
  'opacity',
  'transform',
  'translate',
  'scale',
  'rotate',
  'filter',
  'clip-path',
] as const;

const SKIP = 'data-animate-ui-handoff-skip';

const LAYER = 'data-animate-ui-handoff';

type Layer = {
  menu: string | null;
  to: [number, number];
  fade: Animation | null;
};

const layers = new WeakMap<HTMLElement, Layer>();

const menuOf = (popover: HTMLElement) =>
  popover.id || popover.getAttribute('aria-labelledby') || null;

function translationOf(style: CSSStyleDeclaration): [number, number] {
  const match = style.transform.match(/^matrix\(([^)]+)\)$/);
  if (!match) return [0, 0];
  const values = match[1]!.split(',').map(Number);
  return [values[4] ?? 0, values[5] ?? 0];
}

type ContentCopy = {
  element: HTMLElement;
  menu: string | null;
  left: number;
  top: number;
  scrolls: [Element, number, number][];
};

function freeze(
  original: Element,
  copy: Element,
  scrolls: ContentCopy['scrolls'],
) {
  const style = (copy as Partial<ElementCSSInlineStyle>).style;
  if (style && original.getAnimations().length > 0) {
    const computed = getComputedStyle(original);
    for (const property of ANIMATED_PROPERTIES)
      style.setProperty(property, computed.getPropertyValue(property));
  }
  if (original.scrollTop || original.scrollLeft)
    scrolls.push([copy, original.scrollTop, original.scrollLeft]);
  for (let i = 0; i < original.children.length; i++) {
    const child = copy.children[i];
    if (child) freeze(original.children[i]!, child, scrolls);
  }
}

function copyContent(popover: HTMLElement, nested: Set<HTMLElement>) {
  const computed = getComputedStyle(popover);
  const element = popover.ownerDocument.createElement('div');
  element.setAttribute('aria-hidden', 'true');
  element.setAttribute('inert', '');
  element.setAttribute(LAYER, '');
  Object.assign(element.style, {
    position: 'absolute',
    margin: '0px',
    boxSizing: 'border-box',
    width: `${popover.clientWidth}px`,
    height: `${popover.clientHeight}px`,
    overflow: 'hidden',
    pointerEvents: 'none',
    padding: computed.padding,
    display: computed.display === 'inline' ? 'block' : computed.display,
    flexDirection: computed.flexDirection,
    flexWrap: computed.flexWrap,
    alignItems: computed.alignItems,
    justifyContent: computed.justifyContent,
    gap: computed.gap,
    gridTemplateColumns: computed.gridTemplateColumns,
    gridTemplateRows: computed.gridTemplateRows,
  });
  const skipped: Element[] = [];
  for (const node of nested) {
    if (!popover.contains(node)) continue;
    const top = node.closest('[data-radix-popper-content-wrapper]') ?? node;
    if (popover.contains(top) && top !== popover) {
      top.setAttribute(SKIP, '');
      skipped.push(top);
    }
  }
  const scrolls: ContentCopy['scrolls'] = [];
  if (popover.scrollTop || popover.scrollLeft)
    scrolls.push([element, popover.scrollTop, popover.scrollLeft]);
  for (const node of Array.from(popover.childNodes)) {
    if (
      node instanceof Element &&
      (node.hasAttribute(LAYER) || node.hasAttribute(SKIP))
    )
      continue;
    const copy = node.cloneNode(true);
    if (node instanceof Element && copy instanceof Element) {
      freeze(node, copy, scrolls);
      for (const element of [copy, ...copy.querySelectorAll('*')])
        for (const name of UNIQUE_ATTRIBUTES) element.removeAttribute(name);
      for (const element of copy.querySelectorAll(`[${SKIP}]`))
        element.remove();
    }
    element.appendChild(copy);
  }
  for (const node of skipped) node.removeAttribute(SKIP);
  return {
    element,
    menu: menuOf(popover),
    left: popover.clientLeft,
    top: popover.clientTop,
    scrolls,
  } satisfies ContentCopy;
}

type Leaving = {
  element: HTMLElement;
  menu: string | null;
  box: DOMRect;
  opacity: number;
  slide: [number, number];
  to: [number, number];
};

function leavingIn(popover: HTMLElement): Leaving[] {
  const found: Leaving[] = [];
  for (const element of Array.from(popover.children)) {
    if (!(element instanceof HTMLElement) || !element.hasAttribute(LAYER))
      continue;
    const style = getComputedStyle(element);
    const layer = layers.get(element);
    found.push({
      element,
      menu: layer?.menu ?? null,
      box: element.getBoundingClientRect(),
      opacity: Number(style.opacity),
      slide: translationOf(style),
      to: layer?.to ?? [0, 0],
    });
  }
  return found;
}

type HandoffTimings = {
  move: Transition;
  velocity?: number[];
  since?: number | null;
  out: Transition;
  fadeIn: Transition;
  slideIn: Transition;
};

const running = new WeakMap<HTMLElement, Animation[]>();
const moving = new WeakMap<HTMLElement, { run: Run; animation: Animation }>();

function velocityOfPopover(popover: HTMLElement) {
  const move = moving.get(popover);
  const time = move?.animation.currentTime;
  if (!move || typeof time !== 'number') return [0, 0, 0, 0];
  return velocityOf(move.run, time);
}
const positioned = new WeakSet<HTMLElement>();

function release(popover: HTMLElement) {
  if (!positioned.has(popover) || popover.querySelector(`:scope > [${LAYER}]`))
    return;
  positioned.delete(popover);
  popover.style.position = '';
}

function handOver(
  popover: HTMLElement,
  from: DOMRect,
  previous: ContentCopy,
  leaving: Leaving[],
  timings: HandoffTimings,
) {
  for (const animation of running.get(popover) ?? []) animation.cancel();
  for (const copy of popover.querySelectorAll(`:scope > [${LAYER}]`))
    copy.remove();
  const animations: Animation[] = [];
  running.set(popover, animations);
  const animate = (
    element: Element,
    keyframes: Keyframe[],
    options: KeyframeAnimationOptions,
  ) => {
    const animation = element.animate(keyframes, options);
    animations.push(animation);
    return animation;
  };

  const transform = popover.style.transform;
  popover.style.transform = 'none';
  const to = popover.getBoundingClientRect();
  popover.style.transform = transform;
  const computed = getComputedStyle(popover);
  const items = Array.from(popover.children).filter(
    (item) => !item.hasAttribute(LAYER),
  );

  const shift = motionTokens.shift.handoff;
  const x = from.left - to.left;
  const y = from.top - to.top;
  const offset = [x, y, from.width - to.width, from.height - to.height];
  const curve = curveFrom(
    timings.move,
    offset,
    timings.velocity ?? [0, 0, 0, 0],
  );
  const move = { duration: curve.duration, easing: curve.easing };
  const horizontal = Math.abs(x) >= Math.abs(y);
  const way = -Math.sign(horizontal ? x : y);
  const along = (distance: number): [number, number] =>
    horizontal ? [distance, 0] : [0, distance];

  const menu = menuOf(popover);
  const back = menu
    ? leaving.find((layer) => layer.menu === menu && layer.opacity > 0.02)
    : undefined;
  let enter: { slide: [number, number]; shown: number } = {
    slide: along(way * shift),
    shown: 0,
  };
  const first = items[0];
  const theirs = back?.element.firstElementChild;
  if (back && first && theirs) {
    const own = first.getBoundingClientRect();
    const box = theirs.getBoundingClientRect();
    const rest = Number(getComputedStyle(first).opacity) || 1;
    enter = {
      slide: [box.left - own.left, box.top - own.top],
      shown: Math.min(
        1,
        (back.opacity * Number(getComputedStyle(theirs).opacity)) / rest,
      ),
    };
  }

  const marginRight = parseFloat(computed.marginRight) || 0;
  const marginBottom = parseFloat(computed.marginBottom) || 0;
  const sizing = {
    boxSizing: 'border-box',
    minWidth: '0px',
    maxWidth: 'none',
    minHeight: '0px',
    maxHeight: 'none',
  };
  const moved: Animation[] = [];
  const resize = animate(
    popover,
    [
      {
        ...sizing,
        width: `${from.width}px`,
        height: `${from.height}px`,
        marginRight: `${marginRight + to.width - from.width}px`,
        marginBottom: `${marginBottom + to.height - from.height}px`,
      },
      {
        ...sizing,
        width: `${to.width}px`,
        height: `${to.height}px`,
        marginRight: `${marginRight}px`,
        marginBottom: `${marginBottom}px`,
      },
    ],
    move,
  );
  moving.set(popover, { run: { offset, curve }, animation: resize });
  moved.push(resize);
  const moves = Math.abs(x) >= 0.5 || Math.abs(y) >= 0.5;
  if (moves) {
    const translate = animate(
      popover,
      [{ translate: `${x}px ${y}px` }, { translate: '0px 0px' }],
      {
        ...move,
        composite: 'add',
      },
    );
    moved.push(translate);
  }
  const fadeIn = toCssTiming(timings.fadeIn);
  const slideIn = toCssTiming(timings.slideIn);
  const out = toCssTiming(timings.out);
  const clip = { overflow: 'hidden', whiteSpace: 'nowrap' };
  animate(popover, [clip, clip], {
    duration: Math.max(move.duration, out.duration, fadeIn.duration),
  });

  const [slideX, slideY] = enter.slide;
  const slides = Math.abs(slideX) >= 0.5 || Math.abs(slideY) >= 0.5;
  for (const item of items) {
    const rest = getComputedStyle(item).opacity;
    animate(
      item,
      [{ opacity: Number(rest) * enter.shown }, { opacity: rest }],
      fadeIn,
    );
    if (moves)
      moved.push(
        animate(
          item,
          [{ translate: `${-x}px ${-y}px` }, { translate: '0px 0px' }],
          {
            ...move,
            composite: 'add',
          },
        ),
      );
    if (slides)
      animate(
        item,
        [{ translate: `${slideX}px ${slideY}px` }, { translate: '0px 0px' }],
        {
          ...slideIn,
          composite: 'add',
        },
      );
  }

  if (computed.position === 'static' || positioned.has(popover)) {
    positioned.add(popover);
    popover.style.position = 'relative';
  }
  const originLeft = from.left + popover.clientLeft;
  const originTop = from.top + popover.clientTop;
  const leave = (
    element: HTMLElement,
    {
      menu: layerMenu,
      left,
      top,
      opacity,
      slide,
      to: slideTo,
    }: {
      menu: string | null;
      left: number;
      top: number;
      opacity: number;
      slide: [number, number];
      to: [number, number];
    },
  ) => {
    for (const animation of element.getAnimations()) animation.cancel();
    element.style.left = `${left - originLeft}px`;
    element.style.top = `${top - originTop}px`;
    popover.appendChild(element);
    if (moves)
      moved.push(
        element.animate(
          [{ translate: '0px 0px' }, { translate: `${x}px ${y}px` }],
          { ...move, composite: 'add', fill: 'forwards' },
        ),
      );
    if (slide[0] !== slideTo[0] || slide[1] !== slideTo[1])
      element.animate(
        [
          { transform: `translate(${slide[0]}px, ${slide[1]}px)` },
          { transform: `translate(${slideTo[0]}px, ${slideTo[1]}px)` },
        ],
        { ...out, composite: 'add', fill: 'forwards' },
      );
    const fade = element.animate([{ opacity }, { opacity: 0 }], {
      ...out,
      fill: 'forwards',
    });
    const layer: Layer = { menu: layerMenu, to: slideTo, fade };
    layers.set(element, layer);
    const remove = () => {
      if (layers.get(element)?.fade !== fade) return;
      element.remove();
      release(popover);
    };
    fade.finished.then(remove, remove);
  };

  for (const layer of leaving) {
    if (layer === back) {
      layers.delete(layer.element);
      layer.element.remove();
      continue;
    }
    if (layer.opacity <= 0.02) continue;
    leave(layer.element, {
      menu: layer.menu,
      left: layer.box.left - layer.slide[0],
      top: layer.box.top - layer.slide[1],
      opacity: layer.opacity,
      slide: layer.slide,
      to: layer.to,
    });
  }

  const copy = previous.element;
  leave(copy, {
    menu: previous.menu,
    left: from.left + previous.left,
    top: from.top + previous.top,
    opacity: 1,
    slide: [0, 0],
    to: along(-way * shift),
  });
  for (const [element, top, left] of previous.scrolls) {
    element.scrollTop = top;
    element.scrollLeft = left;
  }

  const timeline = popover.ownerDocument.timeline;
  const now = timeline.currentTime;
  if (
    carries(curve, offset) &&
    typeof now === 'number' &&
    typeof timings.since === 'number'
  ) {
    const since = Math.max(timings.since, now - move.duration);
    for (const animation of moved) animation.startTime = since;
    return;
  }
  for (const animation of moved) animation.pause();
  requestAnimationFrame(() => {
    const start = timeline.currentTime;
    for (const animation of moved)
      if (animation.playState === 'paused') animation.startTime = start;
  });
}

type HandoffOptions = {
  nodeRef: React.RefObject<HTMLElement | null>;
  open: boolean;
  movedOn?: boolean;
  transition: Transition;
  reduce: boolean;
  onDrop?: () => void;
};

type Handoff = {
  from: { opacity: number } | null;
  dropped: boolean;
  entry: HandoffEntry;
};

function isInstant(transition: Transition) {
  return toCssTiming(transition).duration === 0;
}

function useMenuHandoff(
  group: HandoffGroup | null,
  {
    nodeRef,
    open,
    movedOn = false,
    transition,
    reduce,
    onDrop,
  }: HandoffOptions,
): Handoff {
  const [entry] = React.useState(() => new HandoffEntry());
  const enabled = group !== null && !reduce && canAnimate();
  const take = (): Opening => {
    const found = open && enabled ? group.source(entry) : null;
    return {
      open,
      source: found?.entry ?? null,
      skipped: found?.skipped ?? [],
      opacity: found?.entry.node
        ? Number(getComputedStyle(found.entry.node).opacity)
        : 1,
    };
  };
  const [opening, setOpening] = React.useState(take);
  const [dropped, setDropped] = React.useState(false);
  if (opening.open !== open) {
    setOpening(take());
    if (open) setDropped(false);
  }

  const out = useTempoTransition(motionTokens.transition.handoffOut);
  const fadeIn = useTempoTransition(motionTokens.transition.handoffIn);
  const slideIn = useTempoTransition(motionTokens.spring.handoff);
  const timingsRef = React.useRef<HandoffTimings>({
    move: transition,
    out,
    fadeIn,
    slideIn,
  });
  const onDropRef = React.useRef(onDrop);
  React.useLayoutEffect(() => {
    timingsRef.current = { move: transition, out, fadeIn, slideIn };
    onDropRef.current = onDrop;
    entry.attach(nodeRef.current, () => {
      setDropped(true);
      onDropRef.current?.();
    });
  });

  React.useLayoutEffect(() => group?.add(entry), [group, entry]);

  React.useEffect(() => {
    group?.setOpen(entry, open, movedOn);
  }, [entry, group, open, movedOn]);

  React.useLayoutEffect(() => {
    const node = nodeRef.current;
    if (!opening.open || !node) return;
    entry.reopen();
    const source = opening.source;
    if (!source?.node) return;
    entry.await(source);
    const skipped = opening.skipped;
    const from = source.node.getBoundingClientRect();
    const velocity = velocityOfPopover(source.node);
    const since = source.node.ownerDocument.timeline.currentTime;
    const instant = isInstant(timingsRef.current.move);
    const previous = instant ? null : copyContent(source.node, source.nested);
    let swapped = false;
    const swap = () => {
      if (swapped) return;
      swapped = true;
      stop();
      entry.await(null);
      const leaving = previous && source.node ? leavingIn(source.node) : [];
      for (const other of skipped) other.drop();
      source.drop();
      if (node.isConnected && previous)
        handOver(node, from, previous, leaving, {
          ...timingsRef.current,
          velocity,
          since: typeof since === 'number' ? since : null,
        });
      if (source.node) release(source.node);
    };
    const observer =
      typeof ResizeObserver === 'function' ? new ResizeObserver(swap) : null;
    observer?.observe(node);
    const frame = requestAnimationFrame(swap);
    const stop = () => {
      observer?.disconnect();
      cancelAnimationFrame(frame);
    };
    return stop;
  }, [opening, entry, nodeRef]);

  return {
    from: opening.source ? { opacity: opening.opacity } : null,
    dropped,
    entry,
  };
}

function takeOver(
  from: { opacity: number },
  transition: Transition,
): { opacity: number[]; scale: number; transition: Transition } {
  return {
    opacity: [from.opacity, 1],
    scale: 1,
    transition: { ...transition, scale: { duration: 0 } },
  };
}

export {
  HandoffNestedContext,
  MenuHandoffContext,
  takeOver,
  useHandoffGroup,
  useHandoffNested,
  useMenuHandoff,
  freeze,
  release,
  translationOf,
  layers,
  positioned,
  LAYER,
  UNIQUE_ATTRIBUTES,
  type Layer,
  type HandoffTimings,
  type HandoffGroup,
};

import * as React from 'react';
import type { Transition } from 'motion/react';

import {
  motionTokens,
  toCssTiming,
  useShouldReduceMotion,
  useTempoTransition,
} from './context-menu-animated-motion';

const ROWS = [
  '[role^="menuitem"]',
  '[role="option"]',
  '[role="separator"]',
  '[data-slot$="-label"]',
  '[data-slot="navigation-menu-link"]',
  '[data-slot="sidebar-menu-sub-item"]',
].join(',');

const STAGGER = { duration: 0.3, ease: motionTokens.ease.soft, delay: 0.033 };
const SHIFT = 8;
const ARRIVE = { duration: 0.1, ease: motionTokens.ease.out };
const CALM = 10;
const STAGGER_ID = 'animate-ui-stagger';

type StaggerTiming = { duration: number; easing: string; step: number };

function opacityOf(el: Element) {
  let opacity = 1;
  for (let node: Element | null = el; node; node = node.parentElement)
    opacity *= Number(getComputedStyle(node).opacity);
  return opacity;
}

function rowsOf(root: HTMLElement) {
  const rows = [...root.querySelectorAll<HTMLElement>(ROWS)].filter(
    (row) => !row.closest('[data-animate-ui-handoff]'),
  );
  return rows.filter(
    (row) => !rows.some((other) => other !== row && other.contains(row)),
  );
}

function animateRows(rows: HTMLElement[], timing: StaggerTiming) {
  const shift =
    rows[0] && getComputedStyle(rows[0]).direction === 'rtl' ? -SHIFT : SHIFT;
  const step =
    rows.length > CALM
      ? timing.step * Math.sqrt(CALM / rows.length)
      : timing.step;
  return rows.map((row, index) =>
    row.animate(
      [
        {
          opacity: 0,
          filter: motionTokens.blur.surface,
          translate: `${shift}px 0`,
        },
        // No opacity here: it ends on the row's own, a disabled one's 50% or one the library shows late.
        { filter: 'blur(0px)', translate: '0 0' },
      ],
      {
        duration: timing.duration,
        easing: timing.easing,
        delay: index * step,
        fill: 'backwards',
        id: STAGGER_ID,
      },
    ),
  );
}

/** How long until `row` lands from its stagger (0 when it isn't staggering). */
function staggerLeft(row: Element | null) {
  const animation = row
    ?.getAnimations()
    .find((candidate) => candidate.id === STAGGER_ID);
  if (!animation || animation.playState === 'finished') return 0;
  const end = animation.effect?.getComputedTiming().endTime;
  return Math.max(0, Number(end ?? 0) - Number(animation.currentTime ?? 0));
}

/**
 * A just-opened list's rows slide in from the side one after another, out of a blur;
 * rows a library renders a commit later (React Aria's) as they come, before
 * they're painted. `stop` shows them all.
 */
/**
 * Rows slid aside widen what their list can scroll: a library scrolling the
 * chosen one into view (Base UI's combobox) would scroll sideways too, then
 * back as they land. The lists keep their horizontal scroll meanwhile.
 */
function holdScrollX(root: HTMLElement) {
  const lefts = new Map<Element, number>();
  for (const el of [root, ...root.querySelectorAll('*')])
    lefts.set(el, el.scrollLeft);
  const hold = (event: Event) => {
    const target = event.target as Element;
    const left = lefts.get(target);
    if (left !== undefined && target.scrollLeft !== left)
      target.scrollLeft = left;
  };
  root.addEventListener('scroll', hold, true);
  return () => root.removeEventListener('scroll', hold, true);
}

function staggerRows(root: HTMLElement, timing: StaggerTiming) {
  let animations: Animation[] = [];
  let observer: MutationObserver | null = null;
  const release = holdScrollX(root);
  const start = (rows: HTMLElement[]) => {
    animations = animateRows(rows, timing);
    void Promise.all(animations.map((animation) => animation.finished)).then(
      release,
      release,
    );
  };
  const rows = rowsOf(root);
  if (rows.length) start(rows);
  else {
    observer = new MutationObserver(() => {
      const late = rowsOf(root);
      if (!late.length) return;
      observer?.disconnect();
      observer = null;
      start(late);
    });
    observer.observe(root, { childList: true, subtree: true });
    setTimeout(() => {
      if (!observer) return;
      observer.disconnect();
      release();
    }, 300);
  }
  return () => {
    observer?.disconnect();
    for (const animation of animations) animation.finish();
    release();
  };
}

/** Staggers `el`'s rows if it opens from closed: it's still transparent. */
function staggerFromClosed(el: HTMLElement, timing: StaggerTiming) {
  return opacityOf(el) > 0.05 ? null : staggerRows(el, timing);
}

function useStaggerTiming() {
  const transition = useTempoTransition(STAGGER);
  const timingRef = React.useRef<StaggerTiming>(null!);
  React.useLayoutEffect(() => {
    timingRef.current = {
      ...toCssTiming(transition),
      step: (transition.delay ?? 0) * 1000,
    };
  });
  return timingRef;
}

/**
 * Staggers the rows of `ref`'s list as it opens from closed (it starts
 * transparent, or `fresh` says so), not as it comes back while closing or
 * takes over another menu's popover.
 */
function useStaggerOnOpen(
  ref: React.RefObject<HTMLElement | null>,
  open: boolean,
  options: {
    skip?: boolean;
    fresh?: boolean | ((el: HTMLElement) => boolean);
    closed?: (el: HTMLElement) => boolean;
  } = {},
) {
  const reduce = useShouldReduceMotion();
  const timingRef = useStaggerTiming();
  const {
    skip = false,
    fresh,
    closed = (el) => opacityOf(el) <= 0.05,
  } = options;
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!open || reduce || skip || !el) return;
    const opening =
      typeof fresh === 'function' ? fresh(el) : (fresh ?? closed(el));
    if (!opening) return;
    return staggerRows(el, timingRef.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);
}

/** A sidebar's submenu, in a collapsible panel: its sub-items stagger as it unfolds from closed. */
function useSubmenuStagger(
  ref: React.RefObject<HTMLElement | null>,
  open: boolean,
) {
  useStaggerOnOpen(ref, open, {
    closed: (el) =>
      el.offsetHeight < 1 &&
      !!el.querySelector('[data-slot="sidebar-menu-sub"]'),
  });
}

/** A list whose rows stagger: its box is there at once (opacity), its rows bring the fade; under reduced motion, nothing staggers and it fades. */
function useStaggeredEnter(enter: Transition): Transition {
  const reduce = useShouldReduceMotion();
  const arrive = useTempoTransition(ARRIVE);
  return reduce ? enter : { ...enter, opacity: arrive };
}

/**
 * A sidebar submenu's panel is there at once (opacity, blur) while it unfolds,
 * so its sub-items bring the fade: added over the panel's own animation, after it starts.
 */
function quickSubmenuPanel(el: HTMLElement | null) {
  if (!el?.querySelector('[data-slot="sidebar-menu-sub"]')) return;
  queueMicrotask(() => {
    const ends = el
      .getAnimations()
      .map((animation) =>
        Number(animation.effect?.getComputedTiming().endTime ?? 0),
      );
    const total = Math.max(300, ...ends);
    const settled = { opacity: 1, filter: 'blur(0px)' };
    el.animate(
      [
        { ...settled, offset: Math.min(1, 100 / total) },
        { ...settled, offset: 1 },
      ],
      { duration: total, easing: 'ease-out' },
    );
  });
}

/**
 * Whether a list just mounted has been painted once: its first open lays it
 * out before the next paint, long enough for a fade started at mount to be
 * over unseen, so it opens from then.
 */
function usePainted() {
  const [painted, setPainted] = React.useState(false);
  React.useLayoutEffect(() => {
    const frame = requestAnimationFrame(() => setPainted(true));
    return () => cancelAnimationFrame(frame);
  }, []);
  return painted;
}

export {
  quickSubmenuPanel,
  staggerFromClosed,
  useStaggeredEnter,
  staggerLeft,
  useSubmenuStagger,
  staggerRows,
  useStaggerOnOpen,
  useStaggerTiming,
  usePainted,
  type StaggerTiming,
};

'use client';

import * as React from 'react';
import { PresenceContext, type Transition } from 'motion/react';

import {
  motionTokens,
  useCheckAnimation,
  useShouldReduceMotion,
  useTempoTransition,
  type CheckAnimation,
} from './context-menu-animated-motion';
import {
  IndicatorContent,
  mergeRefs,
  type IndicatorContentProps,
  type IndicatorHandle,
} from './context-menu-animated-indicator';
import { glideFrom, stopGlide } from './context-menu-animated-glide';

const DRAW_TRANSITION: Transition = {
  ...motionTokens.transition.check,
  delay: 0,
};
const ERASE_TRANSITION: Transition = motionTokens.transition.uncheck;
const POP_TRANSITION: Transition = motionTokens.spring.checkPop;
const UNPOP_TRANSITION: Transition = motionTokens.transition.popOut;

const GLIDE_TRANSITION = motionTokens.spring.highlight;

const PICK_HOLD: Record<CheckAnimation, number> = { draw: 0.25, pop: 0.15 };

type Picked = CheckAnimation | false;

function usePickHold() {
  const { delay: draw = 0 } = useTempoTransition({ delay: PICK_HOLD.draw });
  const { delay: pop = 0 } = useTempoTransition({ delay: PICK_HOLD.pop });
  return (look: CheckAnimation) => (look === 'draw' ? draw : pop);
}

type ItemCheckAnimationProps = {
  animation?: CheckAnimation;
  transition?: Transition;
};

type GroupReport = {
  handle: IndicatorHandle;
  shown: boolean;
  reduce: boolean;
  glide: Transition;
  rect?: DOMRect;
};

type CheckGroup = { report: (report: GroupReport) => void };

function createCheckGroup(): CheckGroup {
  let pending: GroupReport[] = [];
  const settle = () => {
    const reports = pending;
    pending = [];
    const last = new Map(reports.map((r) => [r.handle.element, r]));
    const shown = [...last.values()].filter((r) => r.shown);
    const hidden = [...last.values()].filter((r) => !r.shown);
    const to = shown.length === 1 ? shown[0]! : null;
    const from =
      to && !to.reduce ? hidden.find((r) => r.handle.isShown()) : undefined;
    if (to && from) {
      const start = from.rect ?? from.handle.element.getBoundingClientRect();
      for (const r of hidden) {
        stopGlide(r.handle.element);
        r.handle.toggle(false, false);
      }
      to.handle.toggle(true, false);
      glideFrom(to.handle.element, start, to.glide);
      return;
    }
    for (const r of hidden) r.handle.toggle(false, true);
    for (const r of shown) r.handle.toggle(true, true);
  };
  return {
    report: (report) => {
      if (pending.length === 0) queueMicrotask(settle);
      pending.push(report);
    },
  };
}

function useCheckGroup(): CheckGroup {
  const [group] = React.useState(createCheckGroup);
  return group;
}

type RegisterCheck = (element: Element, look: CheckAnimation) => () => void;

const CheckRegistryContext = React.createContext<RegisterCheck | null>(null);

function useCheckRegistry() {
  const checksRef = React.useRef(new Map<Element, CheckAnimation>());
  const registerCheck = React.useCallback<RegisterCheck>((element, look) => {
    checksRef.current.set(element, look);
    return () => {
      checksRef.current.delete(element);
    };
  }, []);
  const checkOf = React.useCallback((item?: Element | null): Picked => {
    let found: Picked = false;
    for (const [check, look] of checksRef.current) {
      if (item && !item.contains(check)) continue;
      if (look === 'draw') return 'draw';
      found = look;
    }
    return found;
  }, []);
  const hasCheck = React.useCallback(
    (item?: Element | null) => checkOf(item) !== false,
    [checkOf],
  );
  return { registerCheck, hasCheck, checkOf };
}

type ItemCheckProps = Omit<
  IndicatorContentProps,
  'kind' | 'animation' | 'transition' | 'exitTransition' | 'coordinate'
> &
  ItemCheckAnimationProps & {
    multiple: boolean;
    group: CheckGroup | null;
  };

const settledLists = new WeakSet<Element>();

function inSettledList(check: Element | null) {
  const list = check?.closest('[role="menu"], [role="listbox"]');
  if (!list) return true;
  if (settledLists.has(list)) return true;
  requestAnimationFrame(() => settledLists.add(list));
  return false;
}

function ItemCheck({
  multiple,
  group,
  animation,
  transition,
  ref,
  ...props
}: ItemCheckProps) {
  const look = useCheckAnimation(animation);
  const reduce = useShouldReduceMotion();
  const glide = useTempoTransition(transition ?? GLIDE_TRANSITION);
  const gliding = look === 'pop' && !multiple && group !== null;
  const register = React.use(CheckRegistryContext);
  const elementRef = React.useRef<HTMLElement>(null);
  React.useLayoutEffect(() => {
    const element = elementRef.current;
    return element && register ? register(element, look) : undefined;
  }, [register, look]);
  const mergedRef = React.useMemo(
    () =>
      mergeRefs<HTMLElement>(
        ref as React.Ref<HTMLElement> | undefined,
        elementRef,
        gliding ? asTransformable : undefined,
      ),
    [ref, gliding],
  );
  const coordinate = React.useCallback(
    (handle: IndicatorHandle, shown: boolean) =>
      group?.report({ handle, shown, reduce, glide }),
    [group, reduce, glide],
  );
  const latestRef = React.useRef({ checked: props.checked, reduce, glide });
  React.useLayoutEffect(() => {
    latestRef.current = { checked: props.checked, reduce, glide };
  });
  React.useLayoutEffect(() => {
    const element = elementRef.current;
    if (!gliding || !group || !element) return undefined;
    return () => {
      const { checked, ...latest } = latestRef.current;
      if (!checked || !element.isConnected) return;
      group.report({
        handle: { element, toggle: () => {}, isShown: () => true },
        shown: false,
        rect: element.getBoundingClientRect(),
        ...latest,
      });
    };
  }, [gliding, group]);
  const [enter, exit] =
    look === 'pop'
      ? [POP_TRANSITION, UNPOP_TRANSITION]
      : [DRAW_TRANSITION, ERASE_TRANSITION];

  return (
    <PresenceContext value={null}>
      <IndicatorContent
        {...props}
        ref={mergedRef}
        kind="check"
        animation={look}
        transition={transition ?? enter}
        exitTransition={transition ?? exit}
        coordinate={gliding ? coordinate : undefined}
        animateOnMount={() => inSettledList(elementRef.current)}
      />
    </PresenceContext>
  );
}

function asTransformable(node: HTMLElement | null) {
  if (!node || getComputedStyle(node).display !== 'inline') return;
  const alone = node.parentElement?.childNodes.length === 1;
  node.style.setProperty('display', alone ? 'block' : 'inline-block');
}

type Picks = {
  markPick: (look: CheckAnimation) => void;
  hasCheck: (item?: Element | null) => boolean;
  checkOf: (item?: Element | null) => Picked;
};

const PickContext = React.createContext<Picks | null>(null);

function usePicks() {
  const { registerCheck, hasCheck, checkOf } = useCheckRegistry();
  const pickingRef = React.useRef<Picked>(false);
  const markPick = React.useCallback((look: CheckAnimation) => {
    if (pickingRef.current !== 'draw') pickingRef.current = look;
    setTimeout(() => {
      pickingRef.current = false;
    });
  }, []);
  const wasPicked = React.useCallback(() => pickingRef.current, []);
  const picks = React.useMemo(
    () => ({ markPick, hasCheck, checkOf }),
    [markPick, hasCheck, checkOf],
  );
  return { picks, registerCheck, wasPicked };
}

